# Solution using a stack
def do_algebra(operator, operand):
    stack = []
    for i, num in enumerate(operand):
        if i < len(operator):
            if operator[i] == '+':
                stack.append(stack.pop() + num)
            elif operator[i] == '-':
                stack.append(stack.pop() - num)
            elif operator[i] == '*':
                stack.append(stack.pop() * num)
            elif operator[i] == '//':
                stack.append(stack.pop() // num)
            elif operator[i] == '**':
                stack.append(stack.pop() ** num)
        else:
            stack.append(num)
    return stack.pop()

